import { useState, useEffect, useRef } from 'react';
import sha256 from 'crypto-js/sha256';
import EntrancePage from './pages/Entrance';
import Members from './components/Members';
import LeftSidebar from './components/LeftSidebar';
import RightSideBar from './components/RightSidebar';
import Lobby from './pages/Lobby';
import GamePage from './pages/GamePage';
import VotingModal from './modals/VotingModal';
import './App.css';

let drone = null;

function App() {
  const [roomN, setRoom] = useState(null);
  const [messages, setMessages] = useState([]);
  const [win, setWin] = useState("None");
  const [options, setOptions] = useState({
    bots: 0,
    timeOn: true,
    time: 15,
    bonusTime: 3,
    gorszyObozny: false,
    astroLOG: 3,
    selectedRoles: [],
    hardMode: false,
  });

  const [me, setMe] = useState(
    {
      color: "red",
      username: "noname",
      dev: false,
    }
  );

  const [members, setMembers] = useState([]);
  const [gameState, setGameState] = useState(null);

  const messagesRef = useRef();
  messagesRef.current = messages;
  const membersRef = useRef();
  membersRef.current = members;
  const meRef = useRef();
  meRef.current = me;
  const gameRef = useRef();
  gameRef.current = gameState;
  const optionsRef = useRef();
  optionsRef.current = options;

  function connectToScaledrone() {
    meRef.current.color = "green";
    // meRef.current.username = getName();
    
    drone = new window.Scaledrone('f425Sm8KQuR5wmCc', {
      data: meRef.current,
    });
    drone.on('open', error => {
      if (error) {
        return console.error(error);
      }
      meRef.current.id = drone.clientId;
      setMe(meRef.current);
    });
    const room = drone.subscribe('observable-room-' + roomN);

    room.on('message', message => {
      if (!message?.data)
        return;
      const data = message.data;
      if (!data?.type || !data?.data)
        return;
      if (data.type === "message")
      {
        const m = {...message, data: data.data}
        setMessages([...messagesRef.current, m]);
      }
      else if (data.type === "game")
      {
        if (data.data === "Reset")
          setGameState(null);
        if ((data.data?.version ?? -1) <= (gameRef.current?.version ?? -2))
          return;
        if (meRef?.dev)
          console.log(data.data);
        const winStatus = checkWinCondition(data.data);
        setWin(winStatus);
        if (winStatus !== "None")
          data.data.ended = true;
        setGameState(data.data ?? {});
      }
      else if (data.type === "members")
      {
        setMembers(data.data);
      }
      else if (data.type === "options")
      {
        if (meRef?.dev)
          console.log(data.data);
        setOptions(data.data);
      }
    });
    room.on('members', members => {
      setMembers(members);
    });
    room.on('member_join', member => {
      setMembers([...membersRef.current, member]);
      const message = {type: "options", data: optionsRef.current};
        drone.publish({
          room: "observable-room-" + roomN,
          message
        });
      if (gameRef.current != null)
      {
        const message = {type: "game", data: gameRef.current};
        drone.publish({
          room: "observable-room-" + roomN,
          message
        });
      }
    });
    room.on('member_leave', ({id}) => {
      const index = membersRef.current.findIndex(m => m.id === id);
      const newMembers = [...membersRef.current];
      newMembers.splice(index, 1);
      setMembers(newMembers);
      if (!!gameRef.current)  // game is on
      {
        const seats = gameRef.current.seats;
        const events = gameRef.current?.events ?? [];
        for (let i = 0; i < seats.length; i++)
        {
          if (seats[i].id === id)
          {
            seats[i].removed = true;
            events.push({text: seats[i].username + " wyjechał niespodziewanie z obozu. ", visibility: "all"});
            return;
          }
        }
        onGameStateChange({...gameRef.current, seats: seats, events: events});
      }
    });
  }

  useEffect(() => {
    if (roomN == null)
      return;
    if (drone === null) {
      connectToScaledrone();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [roomN]);

  function setNames(roomName, userName)
  {
    if (roomName === "" || userName === "")
      return;
    setRoom(roomName);
    setMe({...me, username: userName});
  }

  function onGameStateChange(newGameState)
  {
    if (drone === null)
      return;
    if (newGameState && newGameState !== "Reset")
    {
      newGameState.version += 1;
      if (newGameState?.orders && newGameState.orders.length === 0 && !newGameState?.endTime && options.timeOn)
        newGameState.endTime = new Date().getTime() + options.time*60*1000;
    }
    else if (newGameState === "Reset")
      setWin("None");
    const message = {type: "game", data: newGameState};
    drone.publish({
      room: "observable-room-" + roomN,
      message
    });
  }

  function onOptionsChange(newOptions)
  {
    if (drone === null || gameState !== null)
      return;
    const message = {type: "options", data: newOptions};
    drone.publish({
      room: "observable-room-" + roomN,
      message
    });
  }

  function switchDev()
  {
    if (!me?.dev)
    {
      const password = prompt("Dev password:");
      const hash = sha256(password).toString();
      if (hash !== '523435ae129b2967a8488fcd056d4f82e5b7006d7e6b8a9c5f77e1060a7b5508')
        return;
    }
    setMe({...me, dev: !me?.dev});
    const newMembers = members.map(m => m.id === me.id ? {...m, dev: !(m?.dev)} : m);
    const message = {type: "members", data: newMembers};
    drone.publish({
      room: "observable-room-" + roomN,
      message
    });
  }

  function checkWinCondition(gameState)
  {
    if (gameState?.endTime && optionsRef.current.timeOn)
    {
      const d = new Date();
      const remainingTime = gameState.endTime - d.getTime();
      if (remainingTime < 0)
        return "Astrologs";
    }
    let remainingAstrologs = 0;
    let remainingAstronoms = 0;
    let removedAstronoms = 0;
    gameState.seats.forEach((s) => {
      if (s.side === "astrolog" && !(s?.removed || false))
        remainingAstrologs++;
      else if (s.side === "astronom")
      {
        if (!(s?.removed || false))
          remainingAstronoms++;
        else
          removedAstronoms++;
      }
    });
    if (remainingAstrologs === 0)
      return "Astronoms";
    if (removedAstronoms >= (optionsRef.current.hardMode ? 1 : 2))
      return "Astrologs";
    if (remainingAstrologs >= remainingAstronoms)
      return "Astrologs";
    return "None";
  }

  return (
    <div className="App">
      <header>
        <title>Tajni Astrologowie</title>
        <meta name='description' content='Gra w Niewidzialnych Astrologów' />
        <meta name='viewport' content='width=device-width, initial-scale=1' />
        <link rel='icon' href='/favicon.ico' />
      </header>
      <main className="appMain">
        <div className="appContent">
          {roomN ? <>
          <Members members={members} me={me} room={roomN}/>
          <div className={"appGrid " + win + ((gameState && gameState.orders.length > 0) ? " Night" : "")}>
            <LeftSidebar me={me} switchDev={switchDev} options={options} setOptions={onOptionsChange} gameState={gameState} setGameState={onGameStateChange}/>
            {
              gameState ?
              <GamePage gameState={gameState} setGameState={onGameStateChange} me={me} win={win} checkWin={checkWinCondition} options={options}/>
              :
              <Lobby gameState={gameState} setGameState={onGameStateChange} members={members} options={options} setOptions={onOptionsChange}/>
            }
            <RightSideBar gameState={gameState}/>
          </div></> : 
          <EntrancePage setRoom={setNames}/>
          }
        </div>
        <VotingModal gameState={gameState} setGameState={onGameStateChange} me={me} options={options}/>
      </main>
    </div>
  );
}

export default App;
